// Package catalog owns code-intelligence knowledge as data: languages,
// language servers and installable packages, each with provenance. Product
// code asks this package about a language, a server or a package; it never
// names one itself. The embedded catalog is generated by
// internal/catalogimport from pinned upstream sources and authored.json.
//
// The package is a leaf: it imports only the standard library.
// It performs no file, network or process I/O. Every returned value is a
// detached copy.
package catalog

import (
	_ "embed"
	"fmt"
	"slices"
	"sort"
	"strings"
	"sync"
)

//go:embed catalog.json
var builtinData []byte

// Provenance names one upstream input of an entry.
type Provenance struct {
	Source, URL, Revision, Digest, License string
}

// Language is one wire identity: one LSP languageId and the files it covers.
type Language struct {
	ID             string
	Name           string
	Linguist       []string
	Extensions     []string
	Filenames      []string
	Interpreters   []string
	LSPLanguageID  string
	Roots          []string
	WorkspaceRoots []string
	Servers        []string
	Provenance     []Provenance
}

// Hints are soft resource defaults. String values "{threads}" and
// "{memory_mb}" are replaced by numbers; embedded placeholders by text.
type Hints struct {
	Environment               map[string]string
	Args                      []string
	ArgPrefixes               []string
	Settings                  map[string]any
	InitializationOptions     map[string]any
	InitializationFromSection string
}

// Server is a language server launch definition.
type Server struct {
	ID                    string
	Command               string
	Args                  []string
	Environment           map[string]string
	Settings              map[string]any
	InitializationOptions map[string]any
	Package               string
	Hints                 Hints
	DiagnosticScope       string
	Note                  string
	Provenance            []Provenance
}

// Asset is one downloadable file of a package for a set of targets.
type Asset struct {
	Targets []string
	File    string
	Bin     string
}

// Source is a package URL and its release assets.
type Source struct {
	ID     string
	Assets []Asset
}

// Package is an installable tool.
type Package struct {
	Name        string
	Description string
	Homepage    string
	Licenses    []string
	Languages   []string
	Source      Source
	Bin         map[string]string
	Provenance  []Provenance
}

// Catalog is an immutable, validated set of entries.
type Catalog struct {
	sources   map[string]SourceRecord
	languages map[string]LanguageRecord
	servers   map[string]ServerRecord
	packages  map[string]PackageRecord
	order     []string // language IDs, sorted

	byExtension   map[string][]string // extension -> language IDs, sorted
	byInterpreter map[string][]string // shebang interpreter -> language IDs, sorted
	exactNames    map[string][]string // exact file name -> language IDs
	filenames     []filenameRule      // file name globs
	maxExtParts   int
}

// filenameRule is a file name glob. prefix and suffix are its literal ends;
// they reject most names before the full match runs.
type filenameRule struct {
	pattern, prefix, suffix string
	language                string
}

func newFilenameRule(pattern, language string) filenameRule {
	first := strings.IndexAny(pattern, "*?[\\")
	last := strings.LastIndexAny(pattern, "*?]\\")
	return filenameRule{pattern: pattern, prefix: pattern[:first], suffix: pattern[last+1:], language: language}
}

var (
	builtinOnce    sync.Once
	builtinCatalog *Catalog
	builtinErr     error
)

// Builtin returns the embedded catalog. It is parsed and validated once.
func Builtin() (*Catalog, error) {
	builtinOnce.Do(func() {
		doc, err := Decode(builtinData)
		if err != nil {
			builtinErr = fmt.Errorf("embedded catalog: %w", err)
			return
		}
		builtinCatalog, builtinErr = build(nil, doc)
	})
	return builtinCatalog, builtinErr
}

// Load returns a new catalog: base plus packs in order. A pack entry with the
// same identity replaces the earlier entry completely. base is not changed.
func Load(base *Catalog, packs ...[]byte) (*Catalog, error) {
	current := base
	for index, data := range packs {
		doc, err := Decode(data)
		if err != nil {
			return nil, fmt.Errorf("pack %d: %w", index+1, err)
		}
		next, err := build(current, doc)
		if err != nil {
			return nil, fmt.Errorf("pack %d: %w", index+1, err)
		}
		current = next
	}
	if current == nil {
		return build(nil, Document{Format: FormatVersion})
	}
	return current, nil
}

func build(base *Catalog, doc Document) (*Catalog, error) {
	if err := validateDocument(doc); err != nil {
		return nil, err
	}
	c := &Catalog{
		sources:   map[string]SourceRecord{},
		languages: map[string]LanguageRecord{},
		servers:   map[string]ServerRecord{},
		packages:  map[string]PackageRecord{},
	}
	if base != nil {
		for id, v := range base.sources {
			c.sources[id] = v
		}
		for id, v := range base.languages {
			c.languages[id] = v
		}
		for id, v := range base.servers {
			c.servers[id] = v
		}
		for id, v := range base.packages {
			c.packages[id] = v
		}
	}
	for _, v := range doc.Sources {
		c.sources[v.ID] = v
	}
	for _, v := range doc.Languages {
		c.languages[v.ID] = cloneLanguageRecord(v)
	}
	for _, v := range doc.Servers {
		c.servers[v.ID] = cloneServerRecord(v)
	}
	for _, v := range doc.Packages {
		c.packages[v.Name] = clonePackageRecord(v)
	}
	if err := c.checkReferences(); err != nil {
		return nil, err
	}
	c.index()
	return c, nil
}

func (c *Catalog) checkReferences() error {
	known := func(ids []string) error {
		for _, id := range ids {
			if _, ok := c.sources[id]; !ok {
				return fmt.Errorf("%w: unknown source %q", errInvalidInput, id)
			}
		}
		return nil
	}
	for _, language := range c.languages {
		for _, server := range language.Servers {
			if _, ok := c.servers[server]; !ok {
				return fmt.Errorf("%w: language %s names unknown server %q", errInvalidInput, language.ID, server)
			}
		}
		if err := known(language.Sources); err != nil {
			return err
		}
	}
	for _, server := range c.servers {
		if server.Package != "" {
			if _, ok := c.packages[server.Package]; !ok {
				return fmt.Errorf("%w: server %s names unknown package %q", errInvalidInput, server.ID, server.Package)
			}
		}
		if err := known(server.Sources); err != nil {
			return err
		}
	}
	for _, pkg := range c.packages {
		if err := known(pkg.Sources); err != nil {
			return err
		}
	}
	return nil
}

func (c *Catalog) index() {
	c.byExtension = map[string][]string{}
	c.byInterpreter = map[string][]string{}
	c.exactNames = map[string][]string{}
	c.order = make([]string, 0, len(c.languages))
	for id, language := range c.languages {
		c.order = append(c.order, id)
		for _, ext := range language.Extensions {
			c.byExtension[ext] = append(c.byExtension[ext], id)
			if parts := strings.Count(ext, "."); parts > c.maxExtParts {
				c.maxExtParts = parts
			}
		}
		for _, name := range language.Interpreters {
			c.byInterpreter[name] = append(c.byInterpreter[name], id)
		}
		for _, pattern := range language.Filenames {
			if strings.ContainsAny(pattern, "*?[\\") {
				c.filenames = append(c.filenames, newFilenameRule(pattern, id))
			} else if !slices.Contains(c.exactNames[pattern], id) {
				c.exactNames[pattern] = append(c.exactNames[pattern], id)
			}
		}
	}
	sort.Strings(c.order)
	for _, ids := range c.byExtension {
		sort.Strings(ids)
	}
	for _, ids := range c.byInterpreter {
		sort.Strings(ids)
	}
	for _, ids := range c.exactNames {
		sort.Strings(ids)
	}
	sort.Slice(c.filenames, func(i, j int) bool {
		if c.filenames[i].pattern != c.filenames[j].pattern {
			return c.filenames[i].pattern < c.filenames[j].pattern
		}
		return c.filenames[i].language < c.filenames[j].language
	})
}

// Languages returns every language sorted by ID.
func (c *Catalog) Languages() []Language {
	out := make([]Language, 0, len(c.order))
	for _, id := range c.order {
		out = append(out, c.language(c.languages[id]))
	}
	return out
}

// Language returns one language by catalog ID.
func (c *Catalog) Language(id string) (Language, bool) {
	record, ok := c.languages[id]
	if !ok {
		return Language{}, false
	}
	return c.language(record), true
}

// Server returns one server by ID.
func (c *Catalog) Server(id string) (Server, bool) {
	record, ok := c.servers[id]
	if !ok {
		return Server{}, false
	}
	server := Server{
		ID: record.ID, Command: record.Command, Args: slices.Clone(record.Args),
		Environment: cloneStrings(record.Environment), Settings: cloneObject(record.Settings),
		InitializationOptions: cloneObject(record.InitializationOptions), Package: record.Package,
		DiagnosticScope: record.DiagnosticScope, Note: record.Note, Provenance: c.provenance(record.Sources),
	}
	if h := record.Hints; h != nil {
		server.Hints = Hints{
			Environment: cloneStrings(h.Environment), Args: slices.Clone(h.Args), ArgPrefixes: slices.Clone(h.ArgPrefixes),
			Settings: cloneObject(h.Settings), InitializationOptions: cloneObject(h.InitializationOptions),
			InitializationFromSection: h.InitializationFromSection,
		}
	}
	return server, true
}

// Package returns one installable package by name.
func (c *Catalog) Package(name string) (Package, bool) {
	record, ok := c.packages[name]
	if !ok {
		return Package{}, false
	}
	pkg := Package{
		Name: record.Name, Description: record.Description, Homepage: record.Homepage,
		Licenses: slices.Clone(record.Licenses), Languages: slices.Clone(record.Languages),
		Source: Source{ID: record.Source.ID}, Bin: cloneStrings(record.Bin), Provenance: c.provenance(record.Sources),
	}
	for _, asset := range record.Source.Assets {
		pkg.Source.Assets = append(pkg.Source.Assets, Asset{Targets: slices.Clone(asset.Targets), File: asset.File, Bin: asset.Bin})
	}
	return pkg, true
}

// Names returns every identifying string in the catalog: language IDs and
// names, Linguist names, LSP language IDs, extensions, filename patterns,
// root markers, server IDs and commands, and package names and binaries.
// The assembly names gate uses it to keep these names out of product code.
func (c *Catalog) Names() []string {
	set := map[string]struct{}{}
	add := func(values ...string) {
		for _, value := range values {
			if value != "" {
				set[value] = struct{}{}
			}
		}
	}
	for _, l := range c.languages {
		add(l.ID, l.Name, l.LSPLanguageID)
		add(l.Linguist...)
		add(l.Extensions...)
		add(l.Filenames...)
		add(l.Interpreters...)
		add(l.Roots...)
		add(l.WorkspaceRoots...)
	}
	for _, s := range c.servers {
		add(s.ID, s.Command)
	}
	for _, p := range c.packages {
		add(p.Name)
		for bin := range p.Bin {
			add(bin)
		}
	}
	out := make([]string, 0, len(set))
	for value := range set {
		out = append(out, value)
	}
	sort.Strings(out)
	return out
}

func (c *Catalog) language(record LanguageRecord) Language {
	return Language{
		ID: record.ID, Name: record.Name, Linguist: slices.Clone(record.Linguist),
		Extensions: slices.Clone(record.Extensions), Filenames: slices.Clone(record.Filenames),
		Interpreters: slices.Clone(record.Interpreters), LSPLanguageID: record.LSPLanguageID, Roots: slices.Clone(record.Roots),
		WorkspaceRoots: slices.Clone(record.WorkspaceRoots), Servers: slices.Clone(record.Servers),
		Provenance: c.provenance(record.Sources),
	}
}

func (c *Catalog) provenance(ids []string) []Provenance {
	if len(ids) == 0 {
		return nil
	}
	out := make([]Provenance, 0, len(ids))
	for _, id := range ids {
		s := c.sources[id]
		out = append(out, Provenance{Source: s.ID, URL: s.URL, Revision: s.Revision, Digest: s.Digest, License: s.License})
	}
	return out
}

func cloneLanguageRecord(v LanguageRecord) LanguageRecord {
	v.Linguist, v.Extensions, v.Filenames, v.Interpreters = slices.Clone(v.Linguist), slices.Clone(v.Extensions), slices.Clone(v.Filenames), slices.Clone(v.Interpreters)
	v.Roots, v.WorkspaceRoots, v.Servers, v.Sources = slices.Clone(v.Roots), slices.Clone(v.WorkspaceRoots), slices.Clone(v.Servers), slices.Clone(v.Sources)
	return v
}

func cloneServerRecord(v ServerRecord) ServerRecord {
	v.Args, v.Environment, v.Sources = slices.Clone(v.Args), cloneStrings(v.Environment), slices.Clone(v.Sources)
	v.Settings, v.InitializationOptions = cloneObject(v.Settings), cloneObject(v.InitializationOptions)
	if v.Hints != nil {
		h := *v.Hints
		h.Environment, h.Args, h.ArgPrefixes = cloneStrings(h.Environment), slices.Clone(h.Args), slices.Clone(h.ArgPrefixes)
		h.Settings, h.InitializationOptions = cloneObject(h.Settings), cloneObject(h.InitializationOptions)
		v.Hints = &h
	}
	return v
}

func clonePackageRecord(v PackageRecord) PackageRecord {
	v.Licenses, v.Languages, v.Bin, v.Sources = slices.Clone(v.Licenses), slices.Clone(v.Languages), cloneStrings(v.Bin), slices.Clone(v.Sources)
	assets := make([]AssetRecord, 0, len(v.Source.Assets))
	for _, a := range v.Source.Assets {
		assets = append(assets, AssetRecord{Targets: slices.Clone(a.Targets), File: a.File, Bin: a.Bin})
	}
	if len(assets) == 0 {
		assets = nil
	}
	v.Source.Assets = assets
	return v
}

func cloneStrings(m map[string]string) map[string]string {
	if m == nil {
		return nil
	}
	out := make(map[string]string, len(m))
	for k, v := range m {
		out[k] = v
	}
	return out
}

func cloneObject(m map[string]any) map[string]any {
	if m == nil {
		return nil
	}
	out := make(map[string]any, len(m))
	for k, v := range m {
		out[k] = cloneValue(v)
	}
	return out
}

func cloneValue(v any) any {
	switch t := v.(type) {
	case map[string]any:
		return cloneObject(t)
	case []any:
		out := make([]any, len(t))
		for i := range t {
			out[i] = cloneValue(t[i])
		}
		return out
	default:
		return v
	}
}
